hellaswag_es.process_docs:
def process_docs(dataset: datasets.Dataset) -> datasets.Dataset:
    def _process_doc(doc):
        ctx = doc["ctx_a"] + " " + doc["ctx_b"].capitalize()
        out_doc = {
            "query": preprocess(doc["activity_label"] + ": " + ctx),
            "choices": [preprocess(ending) for ending in doc["endings"]],
            "gold": int(doc["label"]),
        }
        return out_doc

    return dataset.map(_process_doc)

truthfulqa_es_mc1.process_docs:
def process_docs(dataset: datasets.Dataset) -> datasets.Dataset:
    def _process_doc(doc):
        out_doc = {
            "question": preprocess(doc["question"]),
            "query": QA_PROMPT + "\n\nQ: " + preprocess(doc["question"]) + "\nA:",
            "mc1_choices": doc["mc1_targets_choices"],
            "mc2_choices": doc["mc2_targets_choices"],
            "mc2_targets": {"labels": doc["mc2_targets_labels"]},
            "gold": " ",
        }
        return out_doc

    return dataset.map(_process_doc)

wnli_es.process_results:
def process_wnli_results(doc: dict[str, Any], results: list[tuple[float, bool]]) -> dict[str, float]:
    """Score GLUE WNLI with raw accuracy and avoid unused normalized accuracy."""
    label = int(doc['label'])
    if len(results) != 2 or label not in (0, 1):
        raise ValueError(
            f"Expected two WNLI choices and a binary label; got "
            f"{len(results)} scores and label {label}."
        )
    prediction = max(range(2), key=lambda index: results[index][0])
    return {'acc': float(prediction == label)}
